def div(n,d,m=1): return None if d in (None,0) else n/d*m
def compute(r):
 e=(r.get('equity_capital') or 0)+(r.get('reserves') or 0); debt=r.get('borrowings') or 0; interest=r.get('interest') or 0; cfo=r.get('operating_activity') or 0;cfi=r.get('investing_activity') or 0
 return {'net_profit_margin_pct':div(r.get('net_profit',0),r.get('sales'),100),'operating_profit_margin_pct':div(r.get('operating_profit',0),r.get('sales'),100),'return_on_equity_pct':None if e<=0 else div(r.get('net_profit',0),e,100),'return_on_capital_employed_pct':div((r.get('operating_profit') or 0)+interest,e+debt,100),'return_on_assets_pct':div(r.get('net_profit',0),r.get('total_assets'),100),'debt_to_equity':0 if debt==0 else (None if e<=0 else debt/e),'interest_coverage':None if interest==0 else ((r.get('operating_profit') or 0)+(r.get('other_income') or 0))/interest,'icr_label':'Debt Free' if interest==0 else None,'asset_turnover':div(r.get('sales',0),r.get('total_assets')),'free_cash_flow_cr':cfo+cfi,'capex_intensity_pct':div(abs(cfi),r.get('sales'),100),'cfo_quality_score':div(cfo,r.get('net_profit'))}
